        listen: L("El hi-hat abierto es el que más mueve.", "The open hi-hat is what moves you most."),
        tracks: [T("d2", "Palmas", "Claps", "percusion", 's "~ cp ~ cp" # gain 0.85 # room 0.15'),
          T("d3", "Hi-hats", "Hi-hats", "percusion", 's "[house:3 house:3 house:4 house:3]*4" # gain "[0.6 0.5 0.85 0.5]*4"')],
        parts: [P("house:4", "El hi-hat abierto del kit, en la tercera semicorchea de cada tiempo (el contratiempo).", "The kit's open hi-hat, on the third sixteenth of each beat (the off-beat)."),
          P("house:3", "El hi-hat cerrado, alrededor.", "The closed hi-hat, around it.")],
