export const courseById = (id) => COURSES.find((c) => c.id === id);

// Lo que suena al terminar el curso (todas las pistas en su última versión, sin máscaras), para «Escuchar el resultado»
export function finalTracks(course) {
  const out = new Map();
  for (const s of course.steps) for (const t of s.tracks || []) out.set(t.id, t);
  return [...out.values()];
}

// "f!4 t!12" → [false×4, true×12]
export function maskArr(str) {
  const out = [];
  for (const tok of str.trim().split(/\s+/)) {
    const m = tok.match(/^([tf])(?:!(\d+))?$/);
    if (!m) continue;
    for (let i = 0; i < (m[2] ? +m[2] : 1); i++) out.push(m[1] === "t");
  }
  return out;
}

// Progreso por curso en este navegador: { merengue: [0,1,2], … }
const KEY = "tidal-studio-courses-v1";
export function courseProgress() { try { return JSON.parse(localStorage.getItem(KEY)) || {}; } catch { return {}; } }
export function markStepDone(id, i) {
  const p = courseProgress();
  p[id] = [...new Set([...(p[id] || []), i])].sort((a, b) => a - b);
  try { localStorage.setItem(KEY, JSON.stringify(p)); } catch {}
}
